import{z as B,x as o,o as n,c as p,q as i,j as t,D as a,d as s,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"计划回归","description":"","frontmatter":{"title":"计划回归","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/plan-regression.md","filePath":"cs/plan-regression.md","lastUpdated":1791063341000}'),d={name:"cs/plan-regression.md"};function C(F,E,f,D,m,c){const r=o("Mermaid");return n(),p("div",null,[E[2]||(E[2]=i('<h1 id="计划回归" tabindex="-1">计划回归 <a class="header-anchor" href="#计划回归" aria-label="Permalink to &quot;计划回归&quot;">​</a></h1><div class="epigraph"><p>同一语句、同一指称，物理树一换，延迟可以差两个数量级。回归是优化器与统计的事故，不是业务写错 SQL。</p><footer>—— 据优化器回归工程实践；Ioannidis 误差敏感；Gray 对测量</footer></div><p><a href="/cs/plan-hints-stability">上一课</a>给出钉计划的手段。本课不罗列 hint 语法。缺口是事故本身：计划回归（plan regression）——软件升级、统计、参数、缓存失效之后选出更差树。优化器单元在此封口；执行引擎单元从 Volcano 迭代器再开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>症状：CPU 或 I/O 突然涨，<code>EXPLAIN</code> 显示连接顺序或算法变了，估计行数与过去差数量级。原因候选：ANALYZE 后直方图变；数据量过阈值；绑定窥视碰到极端参数；代价常数随版本改；学习模型漂移。缺口是<strong>诊断顺序</strong>，不是再讲 DP。</p><p>与查询回归（SQL 写错、缺谓词）分开：那是指称或结果集变。计划回归结果应相同（忽略超时截断）。</p><p><span class="marginnote">捕获前后计划文本、估计与实际行数、当时统计版本，是取证最小集。没有基线计划，回归只能靠人眼。Gray 强调测量；这里测的是优化器输出。</span></p><p><span class="marginnote">「参数窥视」翻译一下：优化器编译语句时偷看了一眼你传进来的具体参数（比如 id=1），按这个值定制计划。等到下次传入的参数命中一半的表，那份「为 id=1 定制」的计划就完全不合适了——这正是窥视的副作用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对比两份计划树。看第一个估计/实际爆炸的节点。检查该节点上的谓词、NDV、是否新索引、是否禁用了下推。修复：更新统计、删误导列组统计、对倾斜参数用重优化、baseline 回滚、或修 sargable。最后才 hint。</p><p>测试：把关键语句的计划形状纳入 CI，升级优化器版本时 diff。这是工程，但是本课缺口的闭合方式。</p>',11)),(n(),t(l,null,{default:a(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLOW%5B%22%E5%BB%B6%E8%BF%9F%E8%B7%B3%E5%8F%98%22%5D%20--%3E%20DIFF%5B%22%E8%AE%A1%E5%88%92%E6%A0%91%20diff%22%5D%0A%20%20DIFF%20--%3E%20NODE%5B%22%E9%A6%96%E4%B8%AA%E5%9F%BA%E6%95%B0%E7%88%86%E7%82%B8%E7%82%B9%22%5D%0A%20%20NODE%20--%3E%20CAUSE%5B%22%E7%BB%9F%E8%AE%A1%20%2F%20%E7%AA%A5%E8%A7%86%20%2F%20%E7%89%88%E6%9C%AC%20%2F%20%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20CAUSE%20--%3E%20FIX%5B%22%E5%88%B7%E6%96%B0%E3%80%81%E5%9F%BA%E7%BA%BF%E5%9B%9E%E6%BB%9A%E6%88%96%E5%90%88%E6%B3%95%E6%94%B9%E5%86%99%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"缓存：旧好计划被淘汰，新优化用新统计选出坏树——表现为「重启后变慢」。自适应可能在单次内修好，日志里仍应留下回归事件以便修根因。",-1)),E[5]||(E[5]=e("p",null,"变慢之后，先回答一个问题：这是「不该变差的变差」吗？",-1)),(n(),t(l,null,{default:a(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%8F%98%E6%85%A2%E4%BA%86%EF%BC%8C%E6%98%AF%E5%9B%9E%E5%BD%92%E5%90%97%EF%BC%9F%22%5D%20--%3E%20C1%5B%22%E6%89%AB%E6%8F%8F%E8%A1%8C%E6%95%B0%E4%B8%8E%E4%B8%9A%E5%8A%A1%E9%87%8F%E5%90%8C%E6%AD%A5%E6%B6%A8%E4%BA%86%EF%BC%9F%22%5D%0A%20%20C1%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E6%95%B0%E6%8D%AE%E7%9C%9F%E6%B6%A8%E4%BA%86%22%7C%20LEGIT%5B%22%E4%B8%8D%E6%98%AF%E5%9B%9E%E5%BD%92%EF%BC%9A%E6%8D%A2%E6%A0%91%E6%98%AF%E5%AF%B9%E7%9A%84%22%5D%0A%20%20C1%20--%3E%7C%22%E5%90%A6%22%7C%20C2%5B%22%E8%AE%A1%E5%88%92%E6%A0%91%E4%B8%8E%E5%8F%98%E6%85%A2%E5%89%8D%E7%9B%B8%E5%90%8C%EF%BC%9F%22%5D%0A%20%20C2%20--%3E%7C%22%E7%9B%B8%E5%90%8C%22%7C%20ENG%5B%22%E6%9F%A5%E6%89%A7%E8%A1%8C%E5%BC%95%E6%93%8E%EF%BC%9A%E7%AE%97%E5%AD%90%E5%B8%B8%E6%95%B0%E5%8F%98%E4%BA%86%22%5D%0A%20%20C2%20--%3E%7C%22%E4%B8%8D%E5%90%8C%22%7C%20REG%5B%22%E6%98%AF%E5%9B%9E%E5%BD%92%EF%BC%9A%E6%B2%BF%E8%AE%A1%E5%88%92%20diff%20%E6%89%BE%E5%9F%BA%E6%95%B0%E7%88%86%E7%82%B8%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">数字实例：计划里某嵌套循环节点估计 10 行、实际 50 万行，误差 5 万倍；内层表每行一次随机读，就多做了约 50 万次 I/O。「延迟差两个数量级」往往就是这样一个节点的估计失真放大出来的。</span></p><p><span class="marginnote">常见误区：把每次慢查询都喊成回归。数据真涨十倍时优化器换树是正确行为；回归特指「不该变差的变差了」。先核对扫描行数与业务量是否同步涨，再下结论。</span></p><p>执行引擎下一单元会改变算子常数（向量化让扫描更便宜），升级引擎等于重校准；也会表现为计划回归，要与「只换统计」分开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Volcano 拉模型。也不把每一次慢查询都叫回归：数据真的涨了十倍，计划换树可能是正确的。回归指定「不该变差的变差了」。</p><p>后课默认：关键语句有计划基线与 diff。执行引擎第一课：物理算子如何真正吐元组。</p><p>优化器单元从 Selinger 搜到回归运维，补的是主干「有计划、有代价」之后的搜索、估计与控制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计划回归是合法但更差的树；用计划 diff 与基数爆炸点定位。</li><li>先统计与基线，后 hint。</li><li>下一单元 Volcano 迭代器：执行模型从「树」落到「next()」。</li><li>出处：Ioannidis；Gray；计划管理实践。</li></ul>',9))])}const _=B(d,[["render",C]]);export{u as __pageData,_ as default};
